$createUser=function(string $username,string $email,string $role='user',string $plan='free')use($pdo): array{$q=$pdo->prepare('INSERT INTO users(public_id,username,display_name,email,email_verified_at,password_hash,role,plan_tier) VALUES(?,?,?,?,NOW(),?,?,?)');$hash=password_hash('correct horse battery staple',PASSWORD_DEFAULT);$q->execute([ulid_like(),$username,ucfirst($username),$email,$hash,$role,$plan]);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);return $q->fetch();};
$admin=$createUser('admin','admin@example.test','admin');$owner=$createUser('owner','owner@example.test');$viewer=$createUser('viewer','viewer@example.test');$researcher=$createUser('researcher','researcher@example.test');$outsider=$createUser('outsider','outsider@example.test');$pro=$createUser('pro','pro@example.test','user','pro');
ok(password_verify('correct horse battery staple',(string)$owner['password_hash']),'native password hashes authenticate correctly');ok(user_plan($pdo,$pro)==='pro'&&user_plan($pdo,$outsider)==='free'&&user_plan($pdo,$admin)==='admin','Free, Pro, and Admin plan boundaries resolve correctly');

