$canonical='https://example.test/article';$pdo->prepare("INSERT INTO sources(public_id,source_type,canonical_url,canonical_url_hash,domain,title) VALUES(?,'article',?,?,'example.test','Example')")->execute([$sourcePublic=ulid_like(),$canonical,hash('sha256',$canonical)]);$sourceId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash) VALUES(?,1,?,?,?,?)')->execute([$sourceId,$canonical,'Example','evidence text',hash('sha256','evidence text')]);$versionId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$versionId,$sourceId]);
$makeAnnotation=function(array $user,string $visibility,?int $teamId=null)use($pdo,$sourceId,$versionId): array{$pdo->prepare("INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text) VALUES(?,?,?,?,'text','evidence text')")->execute([ulid_like(),$sourceId,$versionId,$user['id']]);$capture=(int)$pdo->lastInsertId();$public=ulid_like();$pdo->prepare("INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,visibility,team_id,status) VALUES(?,?,?,?,?,'note',?,?,'published')")->execute([$public,$user['id'],$sourceId,$versionId,$capture,$visibility,$teamId]);$q=$pdo->prepare('SELECT * FROM annotations WHERE id=?');$q->execute([(int)$pdo->lastInsertId()]);return $q->fetch();};
$publicAnnotation=$makeAnnotation($owner,'public');$privateAnnotation=$makeAnnotation($owner,'private');$pdo->prepare('INSERT INTO teams(public_id,owner_user_id,name) VALUES(?,?,?)')->execute([$teamPublic=ulid_like(),$owner['id'],'CI Team']);$teamId=(int)$pdo->lastInsertId();foreach([[$owner,'owner'],[$viewer,'viewer'],[$researcher,'researcher']] as [$tu,$role])$pdo->prepare('INSERT INTO team_members(team_id,user_id,role) VALUES(?,?,?)')->execute([$teamId,$tu['id'],$role]);$teamAnnotation=$makeAnnotation($owner,'team',$teamId);
ok(annotation_access($pdo,$publicAnnotation['public_id'],null)!==null,'public annotation is visible anonymously');ok(annotation_access($pdo,$privateAnnotation['public_id'],null)===null&&annotation_access($pdo,$privateAnnotation['public_id'],$outsider)===null,'private annotation is hidden from anonymous and unrelated users');ok(annotation_access($pdo,$privateAnnotation['public_id'],$owner)!==null,'private annotation remains visible to its owner');ok(annotation_access($pdo,$teamAnnotation['public_id'],$viewer)!==null&&annotation_access($pdo,$teamAnnotation['public_id'],$outsider)===null,'team annotation is limited to team members');

$privateCanonical='https://private.example.test/note';$pdo->prepare("INSERT INTO sources(public_id,source_type,canonical_url,canonical_url_hash,domain,title) VALUES(?,'article',?,?,'private.example.test','Private Example')")->execute([$privateSourcePublic=ulid_like(),$privateCanonical,hash('sha256',$privateCanonical)]);$privateSourceId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash) VALUES(?,1,?,?,?,?)')->execute([$privateSourceId,$privateCanonical,'Private Example','private evidence',hash('sha256','private evidence')]);$privateVersion=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$privateVersion,$privateSourceId]);$pdo->prepare("INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text) VALUES(?,?,?,?,'text','private evidence')")->execute([ulid_like(),$privateSourceId,$privateVersion,$owner['id']]);$privateCapture=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,visibility,status) VALUES(?,?,?,?,?,'private note','private','published')")->execute([ulid_like(),$owner['id'],$privateSourceId,$privateVersion,$privateCapture]);ok(source_access($pdo,$privateSourcePublic,null)===null&&source_access($pdo,$privateSourcePublic,$outsider)===null,'private-only Source is not publicly discoverable');ok(source_access($pdo,$privateSourcePublic,$owner)!==null,'private-only Source remains visible to its authorized owner');ok(users_share_team($pdo,(int)$owner['id'],(int)$viewer['id'])&&!users_share_team($pdo,(int)$owner['id'],(int)$outsider['id']),'Team Only presence is database-scoped');

$pdo->prepare('INSERT INTO research_projects(public_id,owner_user_id,team_id,title) VALUES(?,?,?,?)')->execute([$projectPublic=ulid_like(),$owner['id'],$teamId,'CI Project']);$ownerProject=project_access($pdo,(int)$owner['id'],$projectPublic);$viewerProject=project_access($pdo,(int)$viewer['id'],$projectPublic);$researchProject=project_access($pdo,(int)$researcher['id'],$projectPublic);ok(project_can_write($ownerProject)&&!project_can_write($viewerProject)&&project_can_write($researchProject),'research viewer is read-only while owner/researcher may write');

$stored=private_storage_write($config,'secret evidence bytes','ci','txt');ok(str_starts_with($stored,'private://'),'new evidence uses private:// references');$abs=storage_path_to_absolute($config,$stored);ok($abs!==null&&is_file($abs),'private evidence resolves inside configured private storage');ok(storage_path_to_absolute($config,'private://../escape')===null,'private evidence path traversal is rejected');

